<div x-data="{ receiptOpen: false, receipt: null }" @open-partner-receipt.window="receipt = $event.detail; receiptOpen = true" x-show="receiptOpen" x-cloak class="sbg-modal sbg-v24-overlay sbg-v24-receipt-overlay" role="dialog" aria-modal="true" aria-labelledby="sbg-receipt-title">
    <section class="sbg-modal-panel sbg-v24-receipt-panel"><header class="sbg-v24-modal-header"><div><p class="sbg-v24-eyebrow">A4 PORTRAIT</p><h2 id="sbg-receipt-title">Pratinjau Nota Buah Mitra</h2><p>Periksa barang dan total sebelum mencetak.</p></div><button class="sbg-icon-button" type="button" @click="receiptOpen = false" aria-label="Tutup pratinjau nota" data-dialog-close><x-sbg.icon name="close"/></button></header><div class="sbg-v24-receipt-scroll" tabindex="0" aria-label="Isi nota" x-html="receipt ? SbgReceipt.markup(receipt) : ''"></div><footer class="sbg-v24-receipt-actions"><span>Ukuran cetak: A4 · Portrait</span><button type="button" class="sbg-button sbg-button-primary" @click="receiptOpen = false">Selesai memeriksa</button></footer></section>
</div>
